Usage
```ts
import { parse } from "@ende/yaml/parse";
import { assertEquals } from "@ende/assert";

const data = parse(`
id: 1
name: Alice
`);

assertEquals(data, { id: 1, name: "Alice" });
```

Usage
```ts
import { stringify } from "@ende/yaml/stringify";
import { assertEquals } from "@ende/assert";

const data = { id: 1, name: "Alice" };
const yaml = stringify(data);

assertEquals(yaml, "id: 1\nname: Alice\n");
```

Usage
```ts
import { parse, YamlSyntaxError } from "@ende/yaml";
import { assertInstanceOf } from "@ende/assert";

try {
  parse(`"`);
} catch (error) {
  assertInstanceOf(error, YamlSyntaxError);
  assertInstanceOf(error, SyntaxError);
}
```

Usage
```ts
import { YamlSyntaxError } from "@ende/yaml";
import { assertEquals } from "@ende/assert";

const error = new YamlSyntaxError("Test", { line: 5, column: 10, offset: 50 });
assertEquals(error.line, 5);
```

