Usage
```ts
import { YamlSyntaxError } from "@ende/yaml";
import { assertEquals } from "@ende/assert";

const snippet = "    foo: bar\n         ^";
const error = new YamlSyntaxError(
  "Test",
  { line: 1, column: 6, offset: 5 },
  snippet,
);
assertEquals(error.snippet, snippet);
```

